namespace Merp.Infrastructure.Files;

/// <summary>
/// Where the bytes of files live (D16). Keys are generated by <see cref="FileStore"/>:
/// <c>{tenantId}/{module}/{yyyy}/{MM}/{fileId}</c>, lower case hex, digits and slashes only.
/// </summary>
public interface IFileStorage
{
    /// <summary>Writes a new object; <paramref name="content"/> is read from its current position to the end.</summary>
    Task WriteAsync(string key, Stream content, string contentType, CancellationToken cancellationToken = default);

    /// <summary>Opens an object for reading; throws <see cref="FileNotFoundException"/> when it is missing.</summary>
    Task<Stream> OpenReadAsync(string key, CancellationToken cancellationToken = default);

    /// <summary>Removes an object; a missing object is not an error.</summary>
    Task DeleteAsync(string key, CancellationToken cancellationToken = default);

    /// <summary>Objects whose key starts with <paramref name="prefix"/>, for the orphan sweep.</summary>
    IAsyncEnumerable<StorageObject> ListAsync(string prefix, CancellationToken cancellationToken = default);
}

public sealed record StorageObject(string Key, DateTimeOffset LastModified);

internal static class StorageKeys
{
    /// <summary>Keys never contain anything a path or URL could misread.</summary>
    public static void Validate(string key)
    {
        ArgumentException.ThrowIfNullOrEmpty(key);
        if (key.StartsWith('/') || key.EndsWith('/') || key.Contains("//", StringComparison.Ordinal)
            || !key.All(c => c is '/' or (>= '0' and <= '9') or (>= 'a' and <= 'z')))
        {
            throw new ArgumentException($"'{key}' is not a valid storage key.", nameof(key));
        }
    }
}
